module Admin::ProductsHelper
  # Field configuration for product forms
  # Status: :all (visible for all types), :hide (hidden for specified types), :show (only visible for specified types)
  # Required: array of product types where field is required
  def product_field_config
    {
      # Common fields (all product types)
      name: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },
      price: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },
      product_code: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },
      promo_code: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },
      gl_account: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },
      revenue_code: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },
      status: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },

      # Conditional mandatory fields
      tax: {
        types: :all,
        required: [ "shared_quota", "fixed_quota", "toko" ]
      },
      security_deposit: {
        types: [ "shared_quota", "fixed_quota", "toko" ],
        required: [ "shared_quota", "fixed_quota" ]
      },
      recurrence: {
        types: :all,
        required: [ "shared_quota", "fixed_quota" ]
      },
      description: {
        types: :all,
        required: [ "shared_quota", "fixed_quota" ]
      },
      promo_code_child: {
        types: [ "shared_quota", "toko" ],
        required: [ "shared_quota" ]
      },
      quantity_range: {
        types: :all,
        required: []
      },
      member_limit: {
        types: :all,
        required: [ "shared_quota", "fixed_quota" ]
      },

      # Shared Quota / Fixed Quota specific
      specification: {
        types: [ "shared_quota", "fixed_quota" ],
        required: [ "shared_quota", "fixed_quota" ]
      },

      # Toko specific
      category_product: {
        types: [ "toko" ],
        required: [ "toko" ]
      },
      image_catalog: {
        types: [ "toko" ],
        required: [ "toko" ]
      },
      image_pdp: {
        types: [ "toko" ],
        required: [ "toko" ]
      },
      overview: {
        types: [ "toko" ],
        required: [ "toko" ]
      },
      specification_pdp: {
        types: [ "toko" ],
        required: [ "toko" ]
      }
    }
  end

  # Get data-types attribute value for a field
  def field_data_types(field_name)
    config = product_field_config[field_name.to_sym]
    return "" unless config

    types = config[:types]
    return "shared_quota,fixed_quota,toko" if types == :all

    Array(types).join(",")
  end

  # Get data-required-for attribute value for a field
  def field_data_required_for(field_name)
    config = product_field_config[field_name.to_sym]
    return "" unless config

    Array(config[:required]).join(",")
  end

  def tax_options_with_hints # tax select option with hints
    Product.taxes.keys.map do |tax|
      hint_text = case tax
      when "exclude"
        "tax calculated and added by system"
      else
        "tax already included in listed product price"
      end
      [ tax.titleize + " (#{hint_text})", tax ]
    end
  end

  def display_range(range)
    return "-" if range.blank?
    range[:min] == range[:max] ? range[:min].to_s : "#{range[:min]}-#{range[:max]}"
  end
end

import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["container", "template"]

  connect() {
    this.fieldCount = 0
    this.fields = []
    this.initializeExistingFields()
  }

  initializeExistingFields() {
    // Check if there are existing fields in the container
    const existingFields = this.containerTarget.querySelectorAll('[data-field-index]')
    this.fieldCount = existingFields.length

    // If no existing fields, add one empty field
    if (this.fieldCount === 0) {
      this.addField()
    }
  }

  addField() {
    const fieldHtml = `
      <div class="flex items-center space-x-2 mb-2" data-field-index="${this.fieldCount}">
        <input type="text"
               placeholder="Group"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="group">
        <input type="text"
               placeholder="Name"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="name">
        <input type="text"
               placeholder="Value"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="value">
        <button type="button"
                class="text-red-500 hover:text-red-700 p-2"
                data-action="click->dynamic-fields#removeField">
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
          </svg>
        </button>
      </div>
    `

    this.containerTarget.insertAdjacentHTML('beforeend', fieldHtml)
    this.fieldCount++
    this.updateJsonField()
  }

  removeField(event) {
    const fieldRow = event.target.closest('[data-field-index]')
    if (fieldRow) {
      fieldRow.remove()
      this.updateJsonField()
    }
  }

  updateField() {
    this.updateJsonField()
  }

  updateJsonField() {
    const groupedFields = {}
    const fieldRows = this.containerTarget.querySelectorAll('[data-field-index]')

    fieldRows.forEach(row => {
      const groupInput = row.querySelector('[data-field-type="group"]')
      const nameInput = row.querySelector('[data-field-type="name"]')
      const valueInput = row.querySelector('[data-field-type="value"]')

      const group = groupInput.value.trim()
      const name = nameInput.value.trim()
      const value = valueInput.value.trim()

      if (group && name && value) {
        // Initialize group array if doesn't exist
        if (!groupedFields[group]) {
          groupedFields[group] = []
        }

        // Add name-value pair to the group
        groupedFields[group].push({
          name: name,
          value: value
        })
      }
    })

    // Update the hidden field with JSON
    const hiddenField = document.querySelector('[name="product[specification_pdp]"]')
    if (hiddenField) {
      hiddenField.value = JSON.stringify(groupedFields)
      // Trigger input event to update main form JSON
      hiddenField.dispatchEvent(new Event('input', { bubbles: true }))
    }

    // Trigger custom event for the main form controller
    this.dispatch('fieldUpdated', { detail: { field: 'specification_pdp', value: groupedFields } })
  }
}

