import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["details", "packageSelect", "msisdnField", "msisdnRange"]

  connect() {
    this.productsData = JSON.parse(document.getElementById('products-data').textContent)
    if (this.packageSelectTarget.value) {
      // Set initial MSISDN value and range based on first product
      const firstProduct = this.productsData.find(p => p.id === parseInt(this.packageSelectTarget.value))
      if (firstProduct) {
        const range = this.getMsisdnRange(firstProduct.quantity_range)
        this.msisdnFieldTarget.value = range.min
      }

      this.updateDetails()
      this.updateMsisdnRange()
    }
  }

  updateDetails() {
    const selectedId = parseInt(this.packageSelectTarget.value)
    const product = this.productsData.find(p => p.id === selectedId)

    if (!product) {
      this.detailsTarget.innerHTML = `
        <div class="text-gray-500 text-center">
          Select a product to view details
        </div>
      `
      return
    }

    this.detailsTarget.innerHTML = this.formatProductDetails(product)
    this.updateMsisdnRange()
  }

  updateMsisdnRange() {
    const selectedId = parseInt(this.packageSelectTarget.value)
    const product = this.productsData.find(p => p.id === selectedId)

    if (!product) return

    const range = this.getMsisdnRange(product.quantity_range)

    // Update range text
    const rangeText = range.min === range.max ? 
      `Allowed range: ${range.min} MSISDNs` :
      `Allowed range: ${range.min} - ${range.max} MSISDNs`
    this.msisdnRangeTarget.textContent = rangeText

    // Store range values as data attributes
    this.msisdnFieldTarget.dataset.min = range.min
    this.msisdnFieldTarget.dataset.max = range.max

    // Update field value if needed
    const currentValue = parseInt(this.msisdnFieldTarget.value) || 0
    if (currentValue < range.min || !this.msisdnFieldTarget.value) {
      this.msisdnFieldTarget.value = range.min
    }
  }

  getMsisdnRange(quantity_range) { // buat apa ada method di order kalau di define lg dsini
    switch(quantity_range) {
      case 'q_1_9':
        return { min: 5, max: 10 }
      case 'q_1_25':
        return { min: 11, max: 25 }
      case 'q_1_49':
        return { min: 6, max: 50 }
      case 'q_1_99':
        return { min: 26, max: 100 }
      default:
        return { min: 5, max: 5 }
    }
  }

  validateMsisdnRange(event) {
    const input = event.target
    const value = parseInt(input.value)
    const min = parseInt(input.dataset.min)
    const max = parseInt(input.dataset.max)

    if (value < min || value > max) {
      input.setCustomValidity(`Please enter a value between ${min} and ${max}`)
    } else {
      input.setCustomValidity('')
    }
    input.reportValidity()
  }

  formatProductDetails(product) {
    const price = Number(product.price)
    const security_deposit_with_vat = Math.round((product.security_deposit * 111) / 100)
    const PPN = 11/100

    const parseSpecification = (spec) => {
      if (!spec) return {};
      if (typeof spec === 'string') {
        try {
          return JSON.parse(spec);
        } catch (e) {
          return spec;
        }
      }
      return spec;
    };

    const titleize = (str) => {
      return str
        .split('_')
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');
    };

    const specification = parseSpecification(product.specification);

    const renderSpecification = (spec) => {
      // case for array specs
      if (Array.isArray(spec) && spec.every(item => typeof item === 'object' && item !== null)) {
        const allKeys = [...new Set(spec.flatMap(obj => Object.keys(obj)))];

        let headerRow = `<tr><th class="p-2 border-b">Services</th>`;
        spec.forEach((obj, i) => {
          const header = obj.commercial_name || `Spec ${i + 1}`;
          headerRow += `<th class="p-2 border-b">${header}</th>`;
        });
        headerRow += `</tr>`;

        const bodyRows = allKeys.map((key) => {
          const row = [`<td class="p-2 border-b">${titleize(key)}</td>`];
          spec.forEach((obj) => {
            let val = obj[key];
            if (Array.isArray(val)) {
              val = val.join(', ');
            }
            row.push(`<td class="p-2 border-b">${val ?? 'N/A'}</td>`);
          });
          return `<tr>${row.join('')}</tr>`;
        });

        return [headerRow, ...bodyRows].join('');
      }

      // case for object spec
      if (typeof spec === 'object' && spec !== null) {
        return Object.entries(spec).map(([key, value]) => {
          let formattedValue = Array.isArray(value) ? value.join(', ') : value;
          return `
            <tr>
              <td class="p-2 border-b">${titleize(key)}</td>
              <td class="p-2 border-b">${formattedValue}</td>
            </tr>`;
        }).join('');
      }

      // default case
      return `<tr>
        <td colspan="2" class="p-2">
          <pre class="text-sm text-gray-600 whitespace-pre-wrap">${JSON.stringify(spec, null, 2)}</pre>
        </td>
      </tr>`;
    };

    const basicDetailsTable = `
      <table class="w-full border-collapse text-sm mb-6">
        <thead>
          <tr>
            <th colspan="2" class="text-xl font-semibold text-gray-800 text-left p-2 border-b-2">Detail SKU</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <th colspan="2" class="font-bold text-gray-700 text-left p-2 border-b">Basic Details</th>
          </tr>
          <tr><td class="p-2 border-b">Name</td><td class="p-2 border-b">${product.name}</td></tr>
          <tr><td class="p-2 border-b">Description</td><td class="p-2 border-b">${product.description || 'No description available'}</td></tr>
          <tr><td class="p-2 border-b">Price / Month</td><td class="p-2 border-b">${this.formatCurrency(product.price)}</td></tr>

          <tr>
            <td class="p-2 border-b">Tax</td>
            <td class="p-2 border-b">
              ${product.tax === 'exclude' ? 'Exclude - pajak dihitung terpisah 11%' : (product.tax || 'N/A')}
            </td>
          </tr>

          <tr><td class="p-2 border-b">Recurrence</td><td class="p-2 border-b">${ product.recurrence == 'mrc' ? 'Monthly' : 'One-time' }</td></tr>
          <tr><td class="p-2 border-b">Security Deposit</td><td class="p-2 border-b">Required Payment Upfront</td></tr>
          <tr>
            <td class="p-2 border-b">Security Deposit Amount</td>
            <td class="p-2 border-b">
              ${this.formatCurrency(security_deposit_with_vat)}
            </td>
          </tr>
          <tr>
            <td class="p-2 border-b">Required MSISDN Range</td>
            <td class="p-2 border-b">
              ${this.getMsisdnRangeText(product.quantity_range)}
            </td>
          </tr>
        </tbody>
      </table>
    `;

    const specificationTable = `
      <table class="w-full border-collapse text-sm">
        <thead>
          <tr>
            <th colspan="100%" class="font-bold text-gray-700 text-left p-2 border-b text-lg">Specifications</th>
          </tr>
        </thead>
        <tbody>
          ${renderSpecification(specification)}
        </tbody>
      </table>
    `;

    return basicDetailsTable + specificationTable;
  }

  getMsisdnRangeText(quantity) {
    const range = this.getMsisdnRange(quantity)
    return `${range.min}-${range.max} MSISDNs`
  }

  formatCurrency(amount) {
    return new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR'
    }).format(amount)
  }
}

